  /**
   * @method
   * @name hollaex#cancelAllOrders
   * @description cancel all open orders in a market
   * @see https://apidocs.hollaex.com/#cancel-all-orders
   * @param {string} symbol unified market symbol of the market to cancel orders
   * in
   * @param {object} [params] extra parameters specific to the exchange API
   * endpoint
   * @returns {object[]} a list of [order structures]{@link
   * https://docs.ccxt.com/?id=order-structure}
   */
  std::shared_future<ccxt::any>
  cancelAllOrders(ccxt::any symbol = ccxt::any{},
                  ccxt::any params = ccxt::dict{}) override {
    return std::async(
               std::launch::deferred,
               [=]() mutable -> ccxt::any {
                 if (isTrue(isEqual(symbol, ccxt::any{}))) {
                   throw ArgumentsRequired(toString(add(
                       this->id,
                       std::string(
                           " cancelAllOrders() requires a symbol argument"))));
                 }
                 if (isTrue(isEqual(this->markets, ccxt::any{}))) {
                   awaitValue(this->loadMarkets());
                 }
                 ccxt::any request = ccxt::dict{};
                 ccxt::any market = ccxt::any{};
                 market = this->market(symbol);
                 ::setValue(request, std::string("symbol"),
                            ::getValue(market, std::string("id")));
                 ccxt::any response = awaitValue(this->privateDeleteOrderAll(
                     this->extend(request, params)));
                 //
                 //     [
                 //         {
                 //             "title": "string",
                 //             "symbol": "xht-usdt",
                 //             "side": "sell",
                 //             "size": 1,
                 //             "type": "limit",
                 //             "price": 0.1,
                 //             "id": "string",
                 //             "created_by": 34,
                 //             "filled": 0
                 //         }
                 //     ]
                 //
                 return this->parseOrders(response, market);
               })
        .share();
  }

  /**
   * @method
   * @name hollaex#fetchMyTrades
   * @description fetch all trades made by the user
   * @see https://apidocs.hollaex.com/#get-trades
   * @param {string} symbol unified market symbol
   * @param {int} [since] the earliest time in ms to fetch trades for
   * @param {int} [limit] the maximum number of trades structures to retrieve
   * @param {object} [params] extra parameters specific to the exchange API
   * endpoint
   * @returns {Trade[]} a list of [trade structures]{@link
   * https://docs.ccxt.com/?id=trade-structure}
   */
  std::shared_future<ccxt::any>
  fetchMyTrades(ccxt::any symbol = ccxt::any{}, ccxt::any since = ccxt::any{},
                ccxt::any limit = ccxt::any{},
                ccxt::any params = ccxt::dict{}) override {
    return std::async(
               std::launch::deferred,
               [=]() mutable -> ccxt::any {
                 if (isTrue(isEqual(this->markets, ccxt::any{}))) {
                   awaitValue(this->loadMarkets());
                 }
                 ccxt::any request = ccxt::dict{};
                 ccxt::any market = ccxt::any{};
                 if (isTrue(!isEqual(symbol, ccxt::any{}))) {
                   market = this->market(symbol);
                   ::setValue(request, std::string("symbol"),
                              ::getValue(market, std::string("id")));
                 }
                 if (isTrue(!isEqual(limit, ccxt::any{}))) {
                   ::setValue(request, std::string("limit"),
                              limit); // default 50, max 100
                 }
                 if (isTrue(!isEqual(since, ccxt::any{}))) {
                   ::setValue(request, std::string("start_date"),
                              this->iso8601(since));
                 }
                 ccxt::any response = awaitValue(
                     this->privateGetUserTrades(this->extend(request, params)));
                 //
                 //     {
                 //         "count": 1,
                 //         "data": [
                 //             {
                 //                 "side": "buy",
                 //                 "symbol": "eth-usdt",
                 //                 "size": 0.086,
                 //                 "price": 226.19,
                 //                 "timestamp": "2020-03-03T08:03:55.459Z",
                 //                 "fee": 0.1
                 //             }
                 //         ]
                 //     }
                 //
                 ccxt::any data = this->safeList(response, std::string("data"),
                                                 ccxt::list{});
                 return this->parseTrades(data, market, since, limit);
               })
        .share();
  }

  ccxt::any parseDepositAddress(ccxt::any depositAddress,
                                ccxt::any currency = ccxt::any{}) override {
    //
    //     {
    //         "currency":"usdt",
    //         "address":"TECLD9XBH31XpyykdHU3uEAeUK7E6Lrmik",
    //         "network":"trx",
    //         "standard":null,
    //         "is_valid":true,
    //         "created_at":"2021-05-12T02:43:05.446Z"
    //     }
    //
    ccxt::any address =
        this->safeString(depositAddress, std::string("address"));
    ccxt::any tag = ccxt::any{};
    if (isTrue(!isEqual(address, ccxt::any{}))) {
      ccxt::any parts = split(address, std::string(":"));
      address = this->safeString(parts, 0);
      tag = this->safeString(parts, 1);
    }
    this->checkAddress(address);
    ccxt::any currencyId =
        this->safeString(depositAddress, std::string("currency"));
    currency = this->safeCurrency(currencyId, currency);
    ccxt::any network =
        this->safeString(depositAddress, std::string("network"));
    return ccxt::dict{
        {std::string("info"), depositAddress},
        {std::string("currency"), ::getValue(currency, std::string("code"))},
        {std::string("network"), network},
        {std::string("address"), address},
        {std::string("tag"), tag},
    };
  }

